#include <time.h>
#define _GNU_SOURCE
/* Native mGBA evidence runner. Inputs are GBA key presses; no RAM cheats.
 * Saves exported below are generated by the game's actual SAVE menu.
 * This is a smoke test, NOT a full campaign or Delta certification. */
// Must precede core.h: distro mGBA enables debugger fields in struct mCore.
// Omitting these flags shifted savedataClone by 56 bytes and called a wrong function.
#include <mgba/flags.h>
#include <mgba/core/core.h>
#include <mgba/core/log.h>
#include <stddef.h>
#include <mgba/core/config.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
struct Symbol { uint32_t addr; char name[180]; };
static struct Symbol syms[90000];
static unsigned nsym;
static struct mCore *core;
static color_t pixels[240 * 160];
static const char *outdir;
static int failed;
static void host_log(struct mLogger *logger, int category, enum mLogLevel level, const char *fmt, va_list args) {
    (void)logger; (void)category;
    if (level & (mLOG_ERROR | mLOG_FATAL)) { vfprintf(stderr,fmt,args); fputc('\n',stderr); }
}
static struct mLogger hostLogger = {host_log, NULL};
static void read_party(unsigned char *dst);
static uint32_t native_money(void);
static uint32_t symbol(const char *name) {
    for (unsigned i=0; i<nsym; ++i) if (!strcmp(syms[i].name,name)) return syms[i].addr;
    return 0;
}
static uint32_t rd8(uint32_t a) { return core->busRead8(core,a); }
static uint32_t rd16(uint32_t a) { return core->busRead16(core,a); }
static uint32_t rd32(uint32_t a) { return core->busRead32(core,a); }
// Fixed offsets and party struct size are from this project's pinned Emerald source.
static uint32_t native_money(void) {
    uint32_t sb1=rd32(symbol("gSaveBlock1Ptr")),sb2=rd32(symbol("gSaveBlock2Ptr"));
    return rd32(sb1+0x490)^rd32(sb2+0xac);
}
static void read_party(unsigned char *dst) {
    uint32_t addr=symbol("gPlayerParty");
    for(unsigned i=0;i<600;i++)dst[i]=(unsigned char)rd8(addr+i);
}
static void frames(unsigned n, unsigned keys) {
    core->setKeys(core,keys);
    for (unsigned i=0; i<n; ++i) core->runFrame(core);
    core->setKeys(core,0);
}
static void press(unsigned keys) { frames(2,keys); frames(35,0); }
// Observe the native task's input-ready state; never bypass text/fade safeguards.
static int restart_ready(void) {
    uint32_t task=symbol("gTasks"),func=symbol("Task_AscensionNewGameDecision");
    if(!task || !func)return 0;
    for(unsigned i=0;i<16;i++) {
        uint32_t p=task+i*40;
        if(rd8(p+4) && (rd32(p)&~1u)==(func&~1u) && rd16(p+8+11*2)==1)return 1;
    }
    return 0;
}
static void check(const char *name, int ok) {
    printf("CHECK %s %s\n", ok?"PASS":"FAIL",name); fflush(stdout);
    if (!ok) failed++;
}
static void snapshot(const char *name) {
    char path[1024]; snprintf(path,sizeof(path),"%s/%s.ppm",outdir,name);
    FILE *f=fopen(path,"wb"); if(!f){perror(path);exit(2);}
    fprintf(f,"P6\n240 160\n255\n");
    for(unsigned i=0;i<240*160;i++) {
        unsigned p=pixels[i];
        unsigned char rgb[3]={p&255,(p>>8)&255,(p>>16)&255};
        fwrite(rgb,1,3,f);
    }
    fclose(f);
    uint32_t main=symbol("gMain"), sbp=symbol("gSaveBlock1Ptr");
    uint32_t sb=sbp?rd32(sbp):0, pc=0;
    core->readRegister(core,"pc",&pc);
    printf("STATE %s frame=%u pc=%08x callback2=%08x save_status=%u party=%u sb1=%08x map=%u,%u pos=%u,%u layout=%u\n",name,
           core->frameCounter(core),pc, main?rd32(main+4):0,
           symbol("gSaveFileStatus")?rd16(symbol("gSaveFileStatus")):999,
           symbol("gPlayerPartyCount")?rd8(symbol("gPlayerPartyCount")):999,
           sb,sb?rd8(sb+4):0,sb?rd8(sb+5):0,sb?rd16(sb):0,sb?rd16(sb+2):0,sb?rd16(sb+0x32):0);
    {
        uint32_t xl=symbol("gArenaXLTelemetry"), wa=symbol("gWildlandsWorldAudit"), wt=symbol("gWildlandsWorldTelemetry");
        printf("WORLD %s bgcnt=%04x,%04x,%04x,%04x xl=%u,%u,%u,%u,%u,%u audit=%u,%u,%u,%u,%u,%u,%u,%u tele=%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u\n",name,
            rd16(0x04000008),rd16(0x0400000a),rd16(0x0400000c),rd16(0x0400000e),
            xl?rd32(xl+8):0,xl?rd32(xl+12):0,xl?rd32(xl+24):0,xl?rd32(xl+28):0,
            symbol("sArenaXLCameraX")?(unsigned)(int16_t)rd16(symbol("sArenaXLCameraX")):0,
            symbol("sArenaXLCameraY")?(unsigned)(int16_t)rd16(symbol("sArenaXLCameraY")):0,
            wa?rd32(wa):0,wa?rd32(wa+4):0,wa?rd32(wa+8):0,wa?rd32(wa+12):0,
            wa?rd32(wa+16):0,wa?rd32(wa+20):0,wa?rd32(wa+24):0,wa?rd32(wa+28):0,
            wt?rd32(wt):0,wt?rd32(wt+4):0,wt?rd32(wt+8):0,wt?rd32(wt+12):0,
            wt?rd32(wt+16):0,wt?rd32(wt+20):0,wt?rd32(wt+24):0,wt?rd32(wt+28):0,
            wt?rd32(wt+32):0,wt?rd32(wt+36):0,wt?rd32(wt+40):0,wt?rd32(wt+44):0,
            wt?rd32(wt+48):0,wt?rd32(wt+52):0,wt?rd32(wt+56):0,wt?rd32(wt+60):0);
    }
    {
        uint32_t gb=symbol("sGpuRegBuffer");
        printf("SCROLL %s io=%u,%u/%u,%u/%u,%u buf=%u,%u/%u,%u/%u,%u dispcnt=%04x vcount=%u\n",name,
            rd16(0x04000014),rd16(0x04000016),rd16(0x04000018),rd16(0x0400001a),rd16(0x0400001c),rd16(0x0400001e),
            gb?rd16(gb+0x14):0,gb?rd16(gb+0x16):0,gb?rd16(gb+0x18):0,gb?rd16(gb+0x1a):0,gb?rd16(gb+0x1c):0,gb?rd16(gb+0x1e):0,
            rd16(0x04000000),rd16(0x04000006));
    }
    {
        uint32_t rt=symbol("gRealtimeArenaTelemetry"), ai=symbol("gArenaAiTelemetry"), cap=symbol("sCapture");
        uint32_t so=symbol("gArenaSendoutTelemetry"), ft=symbol("gArenaFrameTelemetry");
        printf("INPUT %s heldRaw=%04x newRaw=%04x held=%04x new=%04x rtFrames=%u rtSpeed=%u rtActive=%u rtPaused=%u aiDec=%u aiPaths=%u wall=%u,%u capture=%u sendout=%u/%u cbUpdates=%u\n",
            name,
            main?rd16(main+0x28):0,main?rd16(main+0x2a):0,
            main?rd16(main+0x2c):0,main?rd16(main+0x2e):0,
            rt?rd32(rt+4):0,rt?rd16(rt+52):0,rt?rd8(rt+56):0,rt?rd8(rt+57):0,
            ai?rd32(ai):0,ai?rd32(ai+4):0,ai?rd32(ai+20):0,ai?rd32(ai+24):0,
            cap?rd8(cap):255,so?rd16(so):0,so?rd16(so+2):0,ft?rd32(ft):0);
    }
    fflush(stdout);
}
static void export_save(const char *name) {
    void *save=NULL;
    size_t size=core->savedataClone(core,&save);
    if(!save || size!=131072){fprintf(stderr,"save export failed: buffer=%p size=%zu (expected 131072)\n",save,size);free(save);exit(2);}
    char path[1024];snprintf(path,sizeof(path),"%s/%s.sav",outdir,name);
    FILE *f=fopen(path,"wb");if(!f){perror(path);free(save);exit(2);}
    size_t written=fwrite(save,1,size,f);int closed=fclose(f);free(save);
    if(written!=size || closed){fprintf(stderr,"save export write/close failed\n");exit(2);}
    printf("SAVE %s bytes=%zu\n",name,size);fflush(stdout);
}
static int is_map(unsigned group,unsigned num) {
    uint32_t a=symbol("gSaveBlock1Ptr"); if(!a)return 0;
    uint32_t sb=rd32(a); return sb && rd8(sb+4)==group && rd8(sb+5)==num;
}
static void save_from_menu(void) {
    press(8); frames(60,0); snapshot("04-start-menu");
    uint32_t acts=symbol("sCurrentStartMenuActions"), count=symbol("sNumStartMenuActions"), cursor=symbol("sStartMenuCursorPos");
    unsigned n=count?rd8(count):0, target=99;
    for(unsigned i=0;i<n && i<10;i++) if(rd8(acts+i)==5)target=i;
    printf("START_MENU count=%u cursor=%u save_slot=%u\n",n,cursor?rd8(cursor):99,target);
    if(target==99){check("native SAVE menu available",0);return;}
    for(unsigned i=0;i<12 && rd8(cursor)!=target;i++)press(128);
    press(1); frames(80,0); snapshot("05-save-prompt");
    for(unsigned i=0;i<4;i++){press(1);frames(150,0);}
    frames(180,0); snapshot("06-after-save");
    check("native save counter advanced",symbol("gSaveCounter") && rd32(symbol("gSaveCounter"))>0);
    check("no damaged flash sectors reported",symbol("gDamagedSaveSectors") && rd32(symbol("gDamagedSaveSectors"))==0);
    export_save("fresh-career");
}

static void dump_words(const char *label,const char *sym,unsigned count){
    uint32_t a=symbol(sym);
    printf("DUMP %s %s",label,sym);
    if(!a){printf(" MISSING\n");fflush(stdout);return;}
    for(unsigned i=0;i<count;i++)printf(" %u",rd32(a+i*4));
    printf("\n");fflush(stdout);
}
static void dump_halves(const char *label,const char *sym,unsigned offset,unsigned count){
    uint32_t a=symbol(sym);
    printf("DUMPH %s %s+%u",label,sym,offset);
    if(!a){printf(" MISSING\n");fflush(stdout);return;}
    for(unsigned i=0;i<count;i++)printf(" %u",rd16(a+offset+i*2));
    printf("\n");fflush(stdout);
}
/* rate LABEL FRAMES KEYS MINPCT: run FRAMES with KEYS held and require the
   Arena frame callback (gArenaFrameTelemetry.updates) to advance on at least
   MINPCT percent of emulated frames. Also reports body-0 travel. */
static void rate(const char *label,unsigned n,unsigned keys,unsigned minpct){
    uint32_t ft=symbol("gArenaFrameTelemetry");
    uint32_t u0=ft?rd32(ft):0,m0=ft?rd32(ft+4):0,f0=core->frameCounter(core);
    frames(n,keys);
    uint32_t u1=ft?rd32(ft):0,m1=ft?rd32(ft+4):0,f1=core->frameCounter(core);
    unsigned pct=(f1>f0)?(unsigned)((u1-u0)*100ull/(f1-f0)):0;
    printf("RATE %s emu_frames=%u arena_updates=%u missed_vblanks=%u pct=%u min=%u\n",label,f1-f0,u1-u0,m1-m0,pct,minpct);
    if(ft){printf("PHASES %s",label);for(unsigned i=0;i<6;i++)printf(" s%u=%u",i,rd16(ft+16+i*2));for(unsigned i=0;i<6;i++)printf(" p%u=%u",i,rd16(ft+28+i*2));printf(" maxGap=%u\n",rd32(ft+8));}
    char name[300];snprintf(name,sizeof(name),"cadence %s",label);
    check(name,ft && pct>=minpct);
}
/* ratesym LABEL SYM OFFSET WIDTH FRAMES KEYS MINPCT: counter delta per emulated frame */
static void ratesym(const char *label,const char *sym,unsigned off,unsigned width,unsigned n,unsigned keys,unsigned minpct){
    uint32_t a=symbol(sym);
    unsigned v0=a?(width==2?rd16(a+off):rd32(a+off)):0,f0=core->frameCounter(core);
    frames(n,keys);
    unsigned v1=a?(width==2?rd16(a+off):rd32(a+off)):0,f1=core->frameCounter(core);
    unsigned d=width==2?(unsigned)((v1-v0)&0xffff):v1-v0;
    unsigned pct=f1>f0?d*100/(f1-f0):0;
    printf("SIMRATE %s emu_frames=%u steps=%u pct=%u min=%u\n",label,f1-f0,d,pct,minpct);
    char name[300];snprintf(name,sizeof(name),"sim cadence %s",label);
    check(name,a && pct>=minpct);
}
/* prof LABEL FRAMES KEYS: instruction-sampled CPU profile by function
 * (every 16th instruction). Measurement only; game state is unchanged. */
struct CodeSym { uint32_t addr; unsigned idx; };
static struct CodeSym csyms[60000]; static unsigned ncsym;
static unsigned long long hits[60001];
static int csym_cmp(const void *a,const void *b){uint32_t x=((const struct CodeSym*)a)->addr,y=((const struct CodeSym*)b)->addr;return x<y?-1:x>y;}
static void prof(const char *label,unsigned n,unsigned keys){
    memset(hits,0,sizeof(hits));
    unsigned long long total=0,steps=0;
    uint32_t f0=core->frameCounter(core);
    core->setKeys(core,keys);
    while(core->frameCounter(core)-f0<n){
        core->step(core);
        if((++steps&15))continue;
        uint32_t pc=0;core->readRegister(core,"pc",&pc);
        unsigned lo=0,hi=ncsym;
        if(pc<0x02000000){hits[60000]++;total++;continue;}
        while(hi-lo>1){unsigned m=(lo+hi)/2;if(csyms[m].addr<=pc)lo=m;else hi=m;}
        if(ncsym&&csyms[lo].addr<=pc){hits[lo]++;total++;}
    }
    core->setKeys(core,0);
    printf("PROF %s frames=%u samples=%llu bios_or_halt=%.1f%%\n",label,n,total,total?hits[60000]*100.0/total:0);
    for(int r=0;r<30;r++){
        unsigned best=0;unsigned long long bv=0;
        for(unsigned i=0;i<ncsym;i++)if(hits[i]>bv){bv=hits[i];best=i;}
        if(!bv)break;
        printf("PROF %s %5.1f%% %s\n",label,bv*100.0/total,syms[csyms[best].idx].name);
        hits[best]=0;
    }
    fflush(stdout);
}
static int commands(const char *path) {
    FILE *f=fopen(path,"r");if(!f){perror(path);return 2;}
    char line[1024],cmd[100],arg[240];unsigned n,k,offset,width,expected;
    struct timespec t0; clock_gettime(CLOCK_MONOTONIC,&t0);
    while(fgets(line,sizeof(line),f)) {
        if(line[0]=='#' || sscanf(line,"%99s",cmd)!=1)continue;
        { struct timespec t1; clock_gettime(CLOCK_MONOTONIC,&t1);
          printf("CMD t=%.1fs frame=%u %s",(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9,core->frameCounter(core),line); fflush(stdout); }
        if(sscanf(line,"frames %u %u",&n,&k)==2)frames(n,k);
        else if(sscanf(line,"press %u",&k)==1)press(k);
        else if(sscanf(line,"snap %239s",arg)==1)snapshot(arg);
        else if(sscanf(line,"save %239s",arg)==1)export_save(arg);
        else if(!strcmp(cmd,"reset")){core->reset(core);}
        else if(!strcmp(cmd,"native_save")){save_from_menu();}
        else if(sscanf(line,"map %u %u",&n,&k)==2)check("expected map",is_map(n,k));
        else if(sscanf(line,"poke %239s %u %u %u",arg,&offset,&width,&expected)==4) {
            uint32_t a=symbol(arg);
            if(a){ if(width==1)core->busWrite8(core,a+offset,expected); else if(width==2)core->busWrite16(core,a+offset,expected); else core->busWrite32(core,a+offset,expected); }
            printf("POKE %s+%u=%u %s\n",arg,offset,expected,a?"ok":"MISSING");fflush(stdout);
            check("poke target exists",a!=0);
        }
        else if(sscanf(line,"ratesym %99s %239s %u %u %u %u %u",cmd,arg,&offset,&width,&n,&k,&expected)==7)ratesym(cmd,arg,offset,width,n,k,expected);
        else if(sscanf(line,"rate %99s %u %u %u",cmd,&n,&k,&expected)==4)rate(cmd,n,k,expected);
        else if(sscanf(line,"prof %99s %u %u",cmd,&n,&k)==3)prof(cmd,n,k);
        else if(sscanf(line,"expectmin %239s %u %u %u",arg,&offset,&width,&expected)==4) {
            uint32_t a=symbol(arg);unsigned value=width==1?rd8(a+offset):width==2?rd16(a+offset):rd32(a+offset);
            char name[300];snprintf(name,sizeof(name),"%s+%u >= %u (got %u)",arg,offset,expected,value);
            check(name,a && value>=expected);
        }
        else if(sscanf(line,"expectmax %239s %u %u %u",arg,&offset,&width,&expected)==4) {
            uint32_t a=symbol(arg);unsigned value=width==1?rd8(a+offset):width==2?rd16(a+offset):rd32(a+offset);
            char name[300];snprintf(name,sizeof(name),"%s+%u <= %u (got %u)",arg,offset,expected,value);
            check(name,a && value<=expected);
        }
        else if(sscanf(line,"dump %99s %239s %u",cmd,arg,&n)==3)dump_words(cmd,arg,n);
        else if(sscanf(line,"expect %239s %u %u %u",arg,&offset,&width,&expected)==4) {
            uint32_t a=symbol(arg);unsigned value=width==1?rd8(a+offset):width==2?rd16(a+offset):rd32(a+offset);
            check(arg,a && value==expected);
        } else {fprintf(stderr,"Unknown command %s",line);fclose(f);return 2;}
    }
    fclose(f);return failed?1:0;
}
int main(int argc,char **argv) {
    if(argc<5){fprintf(stderr,"usage: smoke rom symbols output auto|commands [savefile|-] [citygroup citynum]\n");return 2;}
    outdir=argv[3];mkdir(outdir,0777);
    FILE *sf=fopen(argv[2],"r");if(!sf){perror(argv[2]);return 2;}
    char line[512],type,name[180];unsigned addr;
    while(fgets(line,sizeof(line),sf))if(sscanf(line,"%x %c %179s",&addr,&type,name)==3 && addr>=0x02000000 && addr<0x0a000000 && type!='a' && type!='A' && nsym<90000) {
        if((type=='t'||type=='T'||type=='w'||type=='W')&&ncsym<60000){csyms[ncsym].addr=addr;csyms[ncsym++].idx=nsym;}
        syms[nsym].addr=addr;strcpy(syms[nsym++].name,name);
    }
    qsort(csyms,ncsym,sizeof(csyms[0]),csym_cmp);
    fclose(sf);
    mLogSetDefaultLogger(&hostLogger);
    printf("HOST ABI sizeof(mCore)=%zu savedataClone_offset=%zu\n",sizeof(struct mCore),offsetof(struct mCore,savedataClone));
    core=mCoreFind(argv[1]);
    if(!core || !core->init(core)){fprintf(stderr,"mGBA init failed\n");return 2;}
    mCoreInitConfig(core,NULL);
    struct mCoreOptions opts={0}; opts.useBios=false;opts.skipBios=true;opts.audioBuffers=1024;opts.sampleRate=32768;opts.mute=true;opts.volume=0;opts.logLevel=0;
    mCoreConfigLoadDefaults(&core->config,&opts);mCoreLoadConfig(core);
    core->setVideoBuffer(core,pixels,240);
    if(!mCoreLoadFile(core,argv[1])){fprintf(stderr,"ROM load failed\n");return 2;}
    if(argc>5 && strcmp(argv[5],"-") && !mCoreLoadSaveFile(core,argv[5],true)){fprintf(stderr,"save fixture load failed\n");return 2;}
    if(argc<=5 || !strcmp(argv[5],"-"))
    {
        // Use an isolated erased Flash fixture. Never open a player's main save for writing.
        char fixture[1024]; snprintf(fixture,sizeof(fixture),"%s/%s",outdir,"flash-backend.sav");
        FILE *fp=fopen(fixture,"wb");
        if(!fp){fprintf(stderr,"cannot create flash fixture\n");return 2;}
        unsigned char erased[4096];memset(erased,0xFF,sizeof(erased));
        for(int block=0;block<32;block++) if(fwrite(erased,1,sizeof(erased),fp)!=sizeof(erased)){fprintf(stderr,"flash fixture write failed\n");fclose(fp);return 2;}
        fclose(fp);
        if(!mCoreLoadSaveFile(core,fixture,true)){fprintf(stderr,"flash backend attach failed\n");return 2;}
        printf("TEST FLASH BACKEND: fresh erased 131072-byte save attached; runtime save/export still must pass.\n");
    }
    core->reset(core);
    if(strcmp(argv[4],"auto"))return commands(argv[4]);
    frames(300,0);snapshot("01-title");
    uint32_t title=symbol("Main_AscensionTitle"), main=symbol("gMain");
    check("native Shadow Lugia title callback",title && (rd32(main+4)&~1u)==(title&~1u));
    press(8);frames(150,0);snapshot("02-new-game-menu");
    press(1);frames(480,0);snapshot("03-new-career-city");
    unsigned group=argc>6?(unsigned)atoi(argv[6]):999, num=argc>7?(unsigned)atoi(argv[7]):999;
    int city=is_map(group,num);
    check("NEW GAME reaches Ascension without SELECT",city);
    check("native initial party has six members",symbol("gPlayerPartyCount") && rd8(symbol("gPlayerPartyCount"))==6);
    if(city) {
        save_from_menu();
        uint32_t money=native_money();
        unsigned char party_before[600],party_after[600];read_party(party_before);
        core->reset(core);frames(300,0);press(8);frames(140,0);snapshot("07-continue-menu");
        check("native save loader recognizes valid save",rd16(symbol("gSaveFileStatus"))==1);
        press(1);frames(380,0);snapshot("08-continued-career");
        check("saved career returns to same city",is_map(group,num));
        check("saved party preserved",rd8(symbol("gPlayerPartyCount"))==6);
        check("decrypted native money unchanged after reload",native_money()==money);
        read_party(party_after);check("all six party structs unchanged after reload",!memcmp(party_before,party_after,sizeof(party_before)));
        core->reset(core);frames(300,0);press(8);frames(140,0);press(128);press(1);frames(120,0);
        for(unsigned wait=0;wait<900 && !restart_ready();wait++)frames(1,0);
        check("restart warning is displayed and accepts deliberate input",restart_ready());
        snapshot("09-restart-warning");
        press(2);frames(180,0);snapshot("10-restart-canceled");
        export_save("after-canceled-restart");
        check("cancel restart keeps native save valid",rd16(symbol("gSaveFileStatus"))==1);
        press(1);frames(380,0);snapshot("11-continue-after-cancel");
        check("Continue remains usable after canceled restart",is_map(group,num));
        read_party(party_after);check("cancel did not replace the party",!memcmp(party_before,party_after,sizeof(party_before)));
    }
    printf("RESULT failures=%d; scope=boot/menu/fresh-career/save-smoke-only\n",failed);
    mCoreConfigDeinit(&core->config);core->deinit(core);
    return failed?1:0;
}
